def count_binary_seq(n):
    if n == 0:
        return 1.0

    # Dynamic programming approach to count valid sequences
    dp = [[0] * (n + 1) for _ in range(n + 1)]
    dp[0][0] = 1  # Base case for sum 0 with 0 bits

    # Fill dp table for first n bits
    for i in range(1, n + 1):
        for j in range(n + 1):
            if j - 0 >= 0:
                dp[i][j] += dp[i - 1][j]
            if j - 1 >= 0:
                dp[i][j] += dp[i - 1][j - 1]

    # Sum of first n bits must equal sum of last n bits, so possible sums are from 0 to n
    # Calculate total valid sequences by summing squares of dp[n][k] for k from 0 to n
    total = 0
    for k in range(0, n + 1):
        total += dp[n][k] * dp[n][k]

    return total
