def find_combinations(test_list):
    result = []
    n = len(test_list)

    for i in range(n):
        for j in range(n):
            if i != j:
                sum1 = test_list[i][0] + test_list[j][1]
                sum2 = test_list[i][1] + test_list[j][0]
                if sum1 > sum2:
                    result.append((sum1, sum2))
                elif sum2 > sum1:
                    result.append((sum2, sum1))
                else:
                    result.append((sum1, sum2))

    return sorted(result)
